def transform_grid(grid):
    if not grid or not grid[0]:
        return grid[:][:] if grid else []

    rows, cols = len(grid), len(grid[0])

    # Find connected components
    visited = [[False]*cols for _ in range(rows)]
    rects = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0 and not visited[r][c]:
                cells = []
                queue = [(r, c)]
                visited[r][c] = True
                while queue:
                    cr, cc = queue.pop(0)
                    cells.append((cr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if (0 <= nr < rows and 0 <= nc < cols 
                            and not visited[nr][nc] and grid[nr][nc] == grid[cr][cc]):
                            visited[nr][nc] = True
                            queue.append((nr, nc))

                rmin, rmax = min(x for x,y in cells), max(x for x,y in cells)
                cmin, cmax = min(y for x,y in cells), max(y for x,y in cells)
                rects.append((rmin, cmin, rmax, cmax))

    print("Found rects:", rects)

    # Create color mapping: for each rect, find its immediate inner color
    color_mapping = {}
    for rmin, cmin, rmax, cmax in rects:
        color = grid[rmin][cmin]
        # Look diagonally inward
        inner_color = None
        for ir, ic in [(rmin+1, cmin+1), (rmin+1, cmax-1), (rmax-1, cmin+1), (rmax-1, cmax-1)]:
            if 0 <= ir < rows and 0 <= ic < cols and grid[ir][ic] != 0:
                if grid[ir][ic] != color:
                    inner_color = grid[ir][ic]
                    break

        # If no diagonal neighbor, look at sides
        if inner_color is None:
            for ir, ic in [(rmin+1, cmin), (rmin+1, cmax), (rmax-1, cmin), (rmax-1, cmax)]:
                if 0 <= ir < rows and 0 <= ic < cols and grid[ir][ic] != 0:
                    if grid[ir][ic] != color:
                        inner_color = grid[ir][ic]
                        break

        # If still none (e.g. single cell), look anywhere inside
        if inner_color is None:
            min_r, min_c = rmin + 1, cmin + 1
            max_r, max_c = rmax - 1, cmax - 1
            for ir in range(min_r, max_r + 1):
                for ic in range(min_c, max_c + 1):
                    if grid[ir][ic] != 0:
                        inner_color = grid[ir][ic]
                        break
                if inner_color is not None:
                    break

        color_mapping[color] = inner_color

    print("Color mappings:", color_mapping)

    # Create output using color mapping
    new_grid = [[0]*cols for _ in range(rows)]
    for rmin, cmin, rmax, cmax in rects:
        color = grid[rmin][cmin]
        inner_color = color_mapping.get(color, grid[rmin][cmin])

        for r in range(rmin, rmax + 1):
            for c in range(cmin, cmax + 1):
                new_grid[r][c] = inner_color

    return new_grid

