def is_vertically_symmetric(grid, rows, cols):
    return all(grid[r] == grid[-1-r] for r in range(rows)) if cols > 0 else False

def transform_structure(grid, rows, cols):
    """Transform by reversing layer colors if structure is vertically symmetric."""
    if not is_vertically_symmetric(grid, rows, cols):
        return grid  # Keep as is

    visited = [[False]*cols for _ in range(rows)]
    rects = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0 and not visited[r][c]:
                queue = [(r, c)]
                visited[r][c] = True
                cells = []
                while queue:
                    cr, cc = queue.pop(0)
                    cells.append((cr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if (0 <= nr < rows and 0 <= nc < cols 
                            and not visited[nr][nc] and grid[nr][nc] == grid[cr][cc]):
                            visited[nr][nc] = True
                            queue.append((nr, nc))

                rmin, rmax = min(x for x,y in cells), max(x for x,y in cells)
                cmin, cmax = min(y for x,y in cells), max(y for x,y in cells)
                rects.append((rmin, cmin, rmax, cmax, grid[rmin][cmin]))

    rects_sorted = sorted(rects, key=lambda r: (r[2]-r[0]) + (r[3]-r[1]), reverse=True)
    layer_colors = [r[4] for r in rects_sorted]

    color_map = {layer_colors[i]: layer_colors[-1-1-i] if i != len(layer_colors)-1 else layer_colors[0]
                  for i in range(len(layer_colors))}
    color_map = {layer_colors[i]: layer_colors[-1-i] for i in range(len(layer_colors))}

    output = [[0]*cols for _ in range(rows)]
    for r in rects_sorted:
        rmin, cmin, rmax, cmax, old_color = r
        for rr in range(rmin, rmax + 1):
            for cc in range(cmin, cmax + 1):
                output[rr][cc] = color_map[old_color]

    return output

